"""Builds TABLE.md and the minimal hitting sets. Cell codes: P pass, F fail, N not formulable, ? undetermined;
a trailing * marks an inference (by a reader agent or by this lane), no star = stated or measured in the lane/referee.
Control order: DH HEAT TW+ TW- EA NR B."""
import itertools, json
C = ["DH","HEAT","TW+","TW-","EA","NR","B"]
R = []
def row(id, typ, region, uses, cells, status, stmt, cons):
    c = cells.split(); assert len(c) == 7, id
    R.append(dict(id=id, typ=typ, region=region, uses=uses, cells=c, status=status, stmt=stmt, cons=cons))
