esc = lambda s: s.replace('|','\\|')
with open('TABLE.md','w') as f:
    f.write("# Mechanism table (stack-combinator, 2026-11-16)\n\n")
    f.write("Built from every RESULT.md / REFEREE.md under `tmp/research-2026-11-16/` (eq48, pick, euler, push/*), via the row digests in `rows/G1.md` .. `rows/G4.md` (236 source rows) and direct reading of weil-onesided, g-spinor-square-root, bootstrap, sq-hankel-traces, sq-causal-cascade, sq-krein-index. Referee status wins over lane status.\n\n")
    f.write("Controls. DH = Davenport-Heilbronn. HEAT = backward heat family (tau < 0). TW+ = Lambda(n) -> eps_n Lambda(n) with 0 <= eps_n <= 1. TW- = signed eps_n, |eps_n| <= 1. EA = zeta(s+a) zeta(s-a), 0 < a < 1/2. Two further controls found in the lanes: NR = xi(s)(2 cosh((s-1/2) log q) + c) (ideation-panel T-NR: Euler product, zeta's functional equation, pole at 1, off-line zeros); B = Beurling zeta (sym-power-positivity Thm B: Euler product, Lambda >= 0, pole, no functional equation).\n\n")
    f.write("Cells. P = the control satisfies the statement (the statement cannot separate zeta from it). F = the control violates it. N = not formulable for the control. ? = not determined. A trailing * marks an inference (reader agent or this lane) from the inputs the statement uses; no star = stated or measured in the lane or its referee report. Type: IDENT identity, INEQ proved inequality, INPUT structural property, RIGID rigidity statement, NOGO obstruction, MEAS measured only, TARGET RH-equivalent statement (listed for completeness, never a usable hypothesis).\n\n")
    f.write("| # | id | type | statement | constrains | uses | region | DH | HEAT | TW+ | TW- | EA | NR | B | status |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n")
    for i, r in enumerate(R, 1):
        f.write(f"| {i} | {esc(r['id'])} | {r['typ']} | {esc(r['stmt'])} | {esc(r['cons'])} | {esc(r['uses'])} | {esc(r['region'])} | " + " | ".join(esc(c) for c in r['cells']) + f" | {esc(r['status'])} |\n")
    # minimal hitting sets
    usable = [(i, r) for i, r in enumerate(R, 1) if r['typ'] in ('IDENT','INEQ','INPUT','RIGID')]
    def sig(r, cols, lenient):
        return frozenset(c for c in cols if r['cells'][C.index(c)].startswith('F') or (lenient and r['cells'][C.index(c)].startswith('N')))
    def minimal(cols, lenient):
        sigs = {}
        for i, r in usable:
            s = sig(r, cols, lenient)
            if s: sigs.setdefault(s, []).append(i)
        keys = list(sigs); out = []
        for k in range(1, 5):
            for comb in itertools.combinations(keys, k):
                if frozenset().union(*comb) == frozenset(cols) and not any(set(o) <= set(comb) for o in out):
                    out.append(comb)
        return sigs, out
    f.write("\n## Minimal sets (computed by `gen_table.py`)\n\nA set of usable rows (types IDENT, INEQ, INPUT, RIGID; TARGET, NOGO and MEAS rows excluded) is a hitting set if every control violates at least one member. Rows with the same failure signature are interchangeable, so minimal sets are listed by signature class.\n")
    for title, cols, len_ in (("Strict (F only), brief's controls DH, HEAT, TW+, TW-, EA", C[:5], False), ("Strict (F only), all seven controls", C, False), ("Lenient (F or N), brief's controls", C[:5], True), ("Lenient (F or N), all seven controls", C, True)):
        sigs, out = minimal(cols, len_)
        f.write(f"\n### {title}\n\nSignature classes:\n\n")
        names = {}
        for n, (s, ids) in enumerate(sorted(sigs.items(), key=lambda kv: (-len(kv[0]), sorted(kv[0]))), 1):
            names[s] = f"S{n}"; f.write(f"- S{n} = fails {{{', '.join(c for c in cols if c in s)}}}: rows {ids}\n")
        f.write(f"\nMinimal hitting sets ({len(out)}):\n\n")
        for comb in out: f.write("- {" + ", ".join(names[s] for s in comb) + "}\n")
        print(title, len(out), [[names[s] for s in comb] for comb in out][:12], {names[s]: (sorted(s), ids) for s, ids in sigs.items()})
print(len(R), "rows")
